"""Row addressing: how a watermark key stream is aligned with rows of a (possibly cropped / shuffled / resampled) copy.

time      -> integer tick derived from a timestamp column (best for industrial historian exports)
keys      -> keyed-hash of one or more identifier columns (asset id, batch id, ...)
position  -> row number (breaks under shuffling / cropping; offset search can recover pure crops)
"""
from __future__ import annotations

import hashlib
from dataclasses import dataclass, asdict

import numpy as np
import pandas as pd


@dataclass
class AddressSpec:
    kind: str = "position"            # time | keys | position
    columns: tuple = ()
    tick: float = 1.0                 # ns for datetime columns, native units for numeric time
    time_kind: str = "datetime"       # datetime | numeric

    def to_dict(self) -> dict:
        d = asdict(self); d["columns"] = list(self.columns); return d

    @classmethod
    def from_dict(cls, d: dict) -> "AddressSpec":
        return cls(d["kind"], tuple(d.get("columns", ())), d.get("tick", 1.0), d.get("time_kind", "datetime"))

    @property
    def address_columns(self) -> list[str]:
        return list(self.columns)


def _time_raw(s: pd.Series):
    if pd.api.types.is_numeric_dtype(s):
        return s.to_numpy(dtype=np.float64), "numeric"
    t = pd.to_datetime(s, utc=True, format="mixed")
    return t.dt.as_unit("ns").astype("int64").to_numpy(), "datetime"


def fit_address(df: pd.DataFrame, time_col: str | None = None, key_cols: list[str] | None = None,
                tick: float | None = None) -> AddressSpec:
    if time_col:
        raw, kind = _time_raw(df[time_col])
        if tick is None:
            u = np.unique(raw)
            d = np.diff(u)
            d = d[d > 0]
            if d.size == 0:
                raise ValueError("cannot infer sampling tick from time column")
            tick = float(np.median(d))
        return AddressSpec("time", (time_col,), float(tick), kind)
    if key_cols:
        return AddressSpec("keys", tuple(key_cols))
    return AddressSpec("position")


def compute_address(df: pd.DataFrame, spec: AddressSpec) -> np.ndarray:
    if spec.kind == "position":
        return np.arange(len(df), dtype=np.int64)
    if spec.kind == "time":
        raw, kind = _time_raw(df[spec.columns[0]])
        if kind == "datetime":
            tk = max(int(round(spec.tick)), 1)
            return ((raw + tk // 2) // tk).astype(np.int64)
        return np.rint(raw / spec.tick).astype(np.int64)
    # keys
    sub = df[list(spec.columns)].astype(str)
    joined = sub.iloc[:, 0]
    for c in sub.columns[1:]:
        joined = joined + "\x1f" + sub[c]
    codes, uniq = pd.factorize(joined)
    h = np.fromiter((int.from_bytes(hashlib.blake2b(u.encode(), digest_size=8).digest(), "little") >> 1
                     for u in uniq), dtype=np.int64, count=len(uniq))
    return h[codes]


def time_seconds(df: pd.DataFrame, spec: AddressSpec) -> np.ndarray | None:
    """Seconds (float) for spectral methods; sample index when there is no time axis."""
    if spec.kind != "time":
        return None
    raw, kind = _time_raw(df[spec.columns[0]])
    return raw * 1e-9 if kind == "datetime" else raw
